/**
 * API catalogue — single source of truth for:
 *   - the OpenAPI document served at /api/swagger-json
 *   - the Bruno collection in /bruno (generated by `npm run bruno:generate`)
 *
 * Keep this file free of Nuxt/Nitro imports and non-erasable TypeScript so that
 * plain Node can import it directly (scripts/generate-bruno.mjs, vitest).
 *
 * tests/server/openapi-spec.test.ts fails when a route file under server/api
 * has no entry here, so add an entry whenever you add an endpoint.
 */

export type HttpMethod = 'get' | 'post' | 'put' | 'delete'

export interface QueryParam {
  name: string
  type?: 'string' | 'integer' | 'boolean'
  description?: string
  example?: string | number | boolean
  enum?: string[]
  /** Bruno: include in the request by default (otherwise listed but disabled) */
  enabled?: boolean
}

export interface BodyExample {
  name: string
  zh?: string
  body: unknown
}

export interface Endpoint {
  method: HttpMethod
  /** Full path, path params as {name} */
  path: string
  tag: string
  summary: string
  /** Traditional Chinese title (shown in Bruno docs) */
  zh?: string
  description?: string
  /** No session required */
  public?: boolean
  /** Path param -> Bruno variable holding its value */
  params?: Record<string, string>
  query?: QueryParam[]
  /** JSON body example */
  body?: unknown
  /** Name of a schema in components.schemas describing the body */
  bodySchema?: string
  /** Extra named JSON bodies (each becomes its own Bruno request) */
  examples?: BodyExample[]
  /** multipart/form-data fields */
  multipart?: Record<string, 'file' | 'text'>
  /** Response content type when not JSON */
  produces?: string
  /** Bruno: variable to fill from the response (`data.<field>` or `<field>`) */
  capture?: { var: string, field: string }
  /** Changes or deletes data irreversibly — excluded from smoke runs */
  destructive?: boolean
}

