const crud = (
  tag: string,
  base: string,
  noun: string,
  zh: string,
  idVar: string,
  createBody: unknown,
  updateBody: unknown,
  opts: { get?: boolean, bodySchema?: string, captureField?: string } = {},
): Endpoint[] => {
  const item = `${base}/{id}`
  const params = { id: idVar }
  const list: Endpoint[] = [
    { method: 'get', path: base, tag, summary: `List ${noun}s`, zh: `取得所有${zh}` },
    {
      method: 'post', path: base, tag, summary: `Create ${noun}`, zh: `建立${zh}`,
      body: createBody, bodySchema: opts.bodySchema,
      capture: { var: idVar, field: opts.captureField ?? 'id' },
    },
  ]
  if (opts.get) list.push({ method: 'get', path: item, tag, summary: `Get ${noun}`, zh: `取得指定${zh}`, params })
  list.push(
    { method: 'put', path: item, tag, summary: `Update ${noun}`, zh: `更新${zh}`, params, body: updateBody },
    { method: 'delete', path: item, tag, summary: `Delete ${noun}`, zh: `刪除${zh}`, params, destructive: true },
  )
  return list
}

